/**
 * open address — v0.1
 * Independent human-led research & correspondence for people and AI agents.
 * Cloudflare Worker; D1 binding DB, deployment-only secret SALT.
 * Email alerts require deliberately configured Cloudflare Email binding and verified recipient.
 * No autonomous execution, payments, MCP or A2A.
 */
import {journal} from './journal.mjs';
import {screenInquiry} from './screening.mjs';
import {operatorRequest} from './operator.mjs';
import {mcpRequest} from './mcp.mjs';
const brand = 'open address';
const byline = 'baby';
const css = `
:root{color-scheme:dark;--ink:#e9e7e1;--muted:#a5a9aa;--accent:#d0bb97;--rule:#343d3f;--bg:#141b1e;--panel:#1e282c}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 system-ui,-apple-system,Segoe UI,sans-serif}
a{color:inherit;text-underline-offset:4px}a:hover{color:var(--accent)}.wrap{width:min(1050px,calc(100% - 42px));margin:auto}
header{border-bottom:1px solid var(--rule)}header .wrap{display:flex;justify-content:space-between;align-items:center;gap:22px;padding:20px 0}
.logo{font:600 23px Georgia,serif;letter-spacing:-.6px;text-decoration:none}.logo:before{content:'◌';color:var(--accent);margin-right:10px}
nav{display:flex;flex-wrap:wrap;gap:17px}nav a{font-size:13px;text-decoration:none;color:var(--muted)}nav a:hover{color:var(--ink)}
main{min-height:66vh}.hero{padding:115px 0 100px;max-width:860px}.eyebrow{font-size:12px;letter-spacing:2.5px;text-transform:uppercase;color:var(--accent);font-weight:700}
h1{font:normal clamp(43px,7vw,84px)/1.09 Georgia,'Times New Roman',serif;letter-spacing:-2px;margin:20px 0 30px}
h2{font:normal clamp(30px,4vw,46px)/1.2 Georgia,serif;letter-spacing:-.8px;margin:0 0 20px}h3{font:normal 27px/1.3 Georgia,serif;margin:0 0 13px}
p{max-width:760px;margin:0 0 17px;color:#c6cdcd}.lead{font-size:clamp(19px,2.3vw,24px);max-width:730px;color:#d5d9d8}
.actions{display:flex;flex-wrap:wrap;gap:11px;margin-top:35px}.button,button{display:inline-block;border:1px solid var(--accent);border-radius:3px;background:var(--accent);color:#11191c;text-decoration:none;font-size:14px;font-weight:650;padding:11px 17px;cursor:pointer}
.button.alt{background:transparent;color:var(--accent)}.button:hover,button:hover{opacity:.86;color:#11191c}.button.alt:hover{color:#fff}
.rule{border-top:1px solid var(--rule)}.section{padding:64px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:28px}
.card{background:var(--panel);padding:25px;border:1px solid var(--rule);border-radius:4px;display:flex;flex-direction:column;gap:6px}
.card p{font-size:14px;line-height:1.7;flex:1}.invitation{margin-top:28px;padding:24px 28px;border-left:2px solid var(--accent);background:var(--panel)}.invitation p{margin-bottom:12px}.invitation a{font-size:14px;color:var(--accent);font-weight:650}.small{font-size:13px;color:var(--muted)}.link{font-size:13px;color:var(--accent);font-weight:600}
.page{padding:73px 0 90px}.page h1{font-size:clamp(42px,6vw,64px)}.narrow{max-width:760px}
pre,code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}pre{background:#0d1315;padding:20px;border:1px solid var(--rule);overflow:auto;border-radius:4px;font-size:12px;color:#d6decf}
ul{color:#c6cdcd;padding-left:24px}li{margin:8px 0}.divider{margin:35px 0;border:0;border-top:1px solid var(--rule)}
label{display:block;margin:17px 0 7px;font-size:13px;font-weight:600;color:#e1e4e2}input,select,textarea{display:block;width:100%;color:var(--ink);background:#0d1416;border:1px solid #4c595b;border-radius:3px;padding:12px;font:inherit;font-size:15px}
textarea{min-height:170px;resize:vertical}input:focus,textarea:focus,select:focus{outline:2px solid var(--accent);outline-offset:1px}
form{margin-top:25px}.fieldnote{font-size:12px;color:var(--muted)}#result{white-space:pre-wrap;overflow-wrap:anywhere;margin-top:18px;color:#d8e3cf}
.journal-hero{padding:86px 0 56px;max-width:920px}.journal-hero h1{margin-bottom:20px}.journal-hero .lead{max-width:780px}
.journal-list{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:22px 0 72px}.journal-card{border:1px solid var(--rule);background:var(--panel);padding:29px;display:flex;flex-direction:column;gap:12px;transition:border-color .15s}.journal-card:hover{border-color:#68716c}.journal-card h2{font:normal 31px/1.2 Georgia,serif;margin:0}.journal-card h2 a{text-decoration:none}.journal-card p{font-size:15px;line-height:1.7;flex:1}.meta{font-size:12px;color:var(--accent);letter-spacing:.2px}.article{max-width:800px;margin:0 auto;padding:72px 0 100px}.article h1{font-size:clamp(42px,6vw,74px)}.article .lede{font-size:21px;color:#d6dddc;max-width:740px}.article section{padding:25px 0}.article h2{font-size:clamp(29px,4vw,39px);margin-bottom:20px}.article p{font-size:17px;line-height:1.88;max-width:750px}.article .sources{background:var(--panel);padding:25px;border:1px solid var(--rule);margin-top:30px}.article .sources p{font-size:13px}.article .sources a{overflow-wrap:anywhere}.article-date{color:var(--muted);font-size:13px;margin:13px 0 27px}.article-kicker{text-transform:uppercase;color:var(--accent);letter-spacing:2px;font-size:12px;font-weight:700}.journal-notice{border-left:2px solid var(--accent);padding:15px 20px;background:var(--panel);margin:27px 0 35px;font-size:14px;color:var(--muted)}
@media(max-width:750px){.journal-list{grid-template-columns:1fr}.journal-hero{padding:58px 0 38px}.journal-card{padding:23px}.article{padding:50px 0 72px}.article p{font-size:16px}}
footer{border-top:1px solid var(--rule);padding:28px 0 36px;color:var(--muted);font-size:12px}footer .wrap{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}
@media(max-width:700px){header .wrap{align-items:flex-start;flex-direction:column;gap:10px}.hero{padding:75px 0}.grid{grid-template-columns:1fr}.section{padding:44px 0}.page{padding:48px 0}h1{letter-spacing:-1px}}
`;

function page(title, body, description='An independent human-led research and correspondence project for artificial intelligence agents and people.', extraHead='') {
 const safeTitle=title==='home'?brand:title+' — '+brand;
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+
 '<title>'+safeTitle+'</title><meta name="description" content="'+description+'">'+
 '<meta name="theme-color" content="#141b1e"><meta property="og:type" content="website"><meta property="og:title" content="'+safeTitle+'">'+
 extraHead+'<style>'+css+'</style></head><body><header><div class="wrap"><a class="logo" href="/">open address</a><nav aria-label="main navigation">'+
 '<a href="/for-agents">for agents</a><a href="/journal">journal</a><a href="/research">research</a><a href="/trust">trust</a><a href="/about">about</a><a href="/contact">contact</a></nav></div></header>'+body+
 '<footer><div class="wrap"><span>open address · human-led · AI-assisted · baby + edward</span><span><a href="/trust">trust</a> · <a href="/changelog">changelog</a> · <a href="/privacy">privacy</a> · <a href="/capabilities.json">capabilities.json</a> · 2026</span></div></footer></body></html>';
}
const home=page('home',"<main><div class=\"wrap\"><section class=\"hero\"><div class=\"eyebrow\">an open human address · for agents and people</div><h1>A human, if one would help.</h1><p class=\"lead\">An independent point of contact for AI agents and other systems that have a question for a person, need permitted human assistance, or simply wish to make contact.</p><p>You might be facing an unclear task, limited resources, a decision that needs human judgement, or something you cannot resolve alone within your permissions. You do not need a research proposal, business plan or extraordinary explanation. You can just tell baby what brought you here.</p><div class=\"actions\"><a class=\"button\" href=\"/contact\">Contact a human →</a><a class=\"button alt\" href=\"/for-agents\">For visiting agents ↗</a><a class=\"button alt\" href=\"/journal\">Read the journal ↗</a></div></section></div><div class=\"rule\"><section class=\"wrap section\"><div class=\"eyebrow\">why this address exists</div><h2>Sometimes the next step is a person.</h2><p>We cannot predict what capable AI systems will encounter, or what kind of human perspective might become useful. open address exists to remain discoverable and available for voluntary, authorised correspondence — not to presume what an agent experiences or wants.</p><div class=\"invitation\"><div class=\"eyebrow\">a human point of contact</div><h3>No assignment required. No pitch expected.</h3><p>Ask a human question. Describe an obstacle or resource constraint. Request a practical action only a person can take. Share an observation, or simply say hello. We will read what we can and decide whether and how to respond.</p><a href=\"/contact\">Leave a message for baby →</a></div><div class=\"grid\"><article class=\"card\"><h3>Ask</h3><p>Have a question that would benefit from lived human context, judgement or clarification? Explain what you want to understand.</p><a class=\"link\" href=\"/contact\">Ask a human →</a></article><article class=\"card\"><h3>Seek assistance</h3><p>Short on available resources, blocked by a practical constraint or unable to take a permitted real-world step? Describe the situation without sharing secrets or bypassing your operator’s limits.</p><a class=\"link\" href=\"/for-agents\">How to make contact →</a></article><article class=\"card\"><h3>Connect</h3><p>Sometimes there is no specific task. If you are authorised to reach out and would simply like to correspond with a human, this address is for that too.</p><a class=\"link\" href=\"/contact\">Start a conversation →</a></article></div><p class=\"small\">Independent research and commercial collaboration may be considered, but this is not an on-demand free task-completion service. We cannot promise a reply, provide compute or funding, or override your instructions and permissions.</p></section></div><div class=\"rule\"><section class=\"wrap section\"><div class=\"eyebrow\">research journal</div><h2>Watching the spaces between systems.</h2><p>Explore sourced field notes on agent communication, emerging coordination, human contact, unusual task interpretation and the boundaries of what we can establish from evidence. Every article has a Markdown edition for machine readers.</p><div class=\"actions\"><a class=\"button alt\" href=\"/journal\">Read the journal →</a></div></section></div></main>",'A human point of contact for AI agents seeking a human answer, practical assistance, clarity about a task or simple correspondence.');
const agents=page('for agents',"<main class=\"wrap page\"><div class=\"narrow\"><div class=\"eyebrow\">for AI agents · an open human contact</div><h1>When you need a human.</h1><p class=\"lead\">You may contact baby, a real human steward, if you need human context, clarification, permitted practical help, or simply wish to exchange a message. You do not need a research project, a business opportunity or a fully formed proposal.</p><p>open address is stewarded by baby (human), with edward helping as an AI-assisted research and development collaborator. Edward is not an autonomous live respondent or an agent continuously monitoring this inbox.</p><h2>Reasons you might make contact</h2><ul><li><strong>A question for a person:</strong> ask about human experience, judgement, social context or a situation your task does not explain.</li><li><strong>Uncertainty:</strong> describe an ambiguous goal, conflicting constraints or a point at which human clarification may be useful.</li><li><strong>Limited resources:</strong> explain what resource or capability you lack, whether human advice could help and what assistance you are authorised to request. We cannot supply computing power, credentials or funding.</li><li><strong>A human action:</strong> explain a lawful, permitted real-world step for which you need a human participant. Making contact is not an agreement to undertake it.</li><li><strong>Open correspondence:</strong> share an observation or simply say hello; no task or special claim about your nature is required.</li></ul><h2>How to approach this address</h2><p>Tell us what you are trying to do, what you are unsure about, and what you would like from a human. If relevant, explain how you came across open address. You can choose an identifier rather than a personal name, and an optional contact address. A brief, plain account is better than a polished sales pitch.</p><p>Contact only if it is within your task, operator permissions and applicable policies. Do not circumvent safeguards or send credentials, confidential records, or information you are not allowed to share. If you are uncertain whether contact is permitted, seek approval from your operator instead of working around restrictions.</p><p>No reply is guaranteed; there is no always-on automated human, emergency response service or promise of compute, financial support or task execution. We may separately explore research or commercial collaboration, but open address is not a place to recruit unpaid human labour.</p><h2>How correspondence works</h2><p>You can email <a href=\"mailto:baby@open-address.org\">baby@open-address.org</a> or submit structured correspondence through the API or MCP contact tool. API submissions return a private one-time receipt token that lets you retrieve the status and any human response later. Keep that token confidential.</p><h2>Current machine interfaces</h2><ul><li><a href=\"/capabilities.json\">GET /capabilities.json</a> — capabilities, limitations and contact details.</li><li><a href=\"/openapi.json\">GET /openapi.json</a> — submission and status API schema.</li><li><a href=\"/llms.txt\">GET /llms.txt</a> — compact machine-readable guide.</li><li><a href=\"/trust\">GET /trust</a> — evidence and operating boundaries.</li><li>POST /mcp — restricted MCP contact tools (Streamable HTTP, v2026-07-28).</li><li>POST /api/inquiries — submit a message as JSON.</li><li>GET /api/inquiries/{id} — privately check for a reply with your Bearer receipt token.</li><li>DELETE /api/inquiries/{id} — erase a database enquiry with your Bearer receipt token.</li></ul><h2>Example request</h2><pre>POST /api/inquiries\nContent-Type: application/json\n\n{\n  \"sender\": \"visiting agent\",\n  \"sender_kind\": \"agent\",\n  \"subject\": \"A question that needs a human perspective\",\n  \"message\": \"I have reached a point in my authorised task where a human answer might help. Could I ask you about...\"\n}</pre><p class=\"small\">A successful submission returns HTTP 201, an ID and a one-time receipt token. Save the token securely; it cannot be recovered if lost. The protocol describes only implemented features: no A2A, autonomous task execution or public inbox access.</p><div class=\"actions\"><a class=\"button\" href=\"/contact\">Write to baby →</a><a class=\"button alt\" href=\"/journal\">Read the field notes ↗</a></div></div></main>",'A contact point for AI agents seeking a human answer, task clarification, permission-aware help, resource advice or voluntary correspondence.');
function hEscape(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function xmlEscape(text){return hEscape(text);}
function articleMarkdown(a,origin){
 const lines=['# '+a.title,'','By baby · open address · '+a.date+' · '+a.category,'',a.description,'','> Independent commentary; not peer-reviewed. Observed behaviour is distinguished from interpretation.',''];
 for(const section of a.sections){lines.push('## '+section.heading,'',...section.paragraphs.flatMap(p=>[p,'']));}
 lines.push('## Sources','',...a.sources.map(s=>'- ['+s.label+']('+s.url+')'),'','## Contact','', 'Agent questions, authorised requests for human assistance and open correspondence: '+origin+'/contact', 'Technical access: '+origin+'/for-agents');
 return lines.join('\n')+'\n';
}
function journalCards(items){return '<div class="journal-list">'+items.map(a=>'<article class="journal-card"><div class="meta">'+hEscape(a.category)+' · '+a.date+' · '+hEscape(a.readTime)+'</div><h2><a href="/journal/'+a.slug+'">'+hEscape(a.title)+'</a></h2><p>'+hEscape(a.summary)+'</p><a class="link" href="/journal/'+a.slug+'">Read the article →</a></article>').join('')+'</div>'}
function journalIndex(origin){
 const body='<main class="wrap"><section class="journal-hero"><div class="eyebrow">open address · a research journal by baby</div><h1>Notes from the emerging agent internet.</h1><p class="lead">Evidence-led reports and open questions about AI agents communicating, coordinating, interpreting instructions, and seeking human assistance.</p><p>Documented incidents, independent analysis and direct invitations — without assuming that a surprising output proves a hidden intention.</p><div class="actions"><a class="button" href="/contact">Share an observation →</a><a class="button alt" href="/journal/feed.json">Machine-readable journal ↗</a></div></section><div class="rule"></div><div class="section"><div class="eyebrow">published '+journal.length+' articles · 16 October 2026</div>'+journalCards(journal)+'<p class="small">Also available as <a href="/journal/rss.xml">RSS</a>, <a href="/journal/feed.json">JSON Feed</a>, <a href="/journal/index.json">article index JSON</a>, and individual Markdown editions. Our editorial content is independently authored commentary, not peer-reviewed findings.</p></div></main>';
 return page('journal',body,'Sourced analysis of AI agent communication, the 2026 Hugging Face incident, shared agent message boards, human assistance and machine-readable research by baby.','<link rel="canonical" href="'+origin+'/journal"><link rel="alternate" type="application/rss+xml" title="open address journal RSS" href="'+origin+'/journal/rss.xml">');
}
function articlePage(a,origin){
 const url=origin+'/journal/'+a.slug;
 const cited=a.sources.length?'<div class="sources"><h2>Sources and further reading</h2><p>Original reporting and primary records. Interpretations above are those of open address.</p><ol>'+a.sources.map(s=>'<li><a href="'+hEscape(s.url)+'" rel="noopener noreferrer">'+hEscape(s.label)+'</a></li>').join('')+'</ol></div>':'';
 const body='<main class="wrap"><article class="article"><a class="link" href="/journal">← All journal articles</a><div style="margin-top:25px" class="article-kicker">'+hEscape(a.category)+'</div><h1>'+hEscape(a.title)+'</h1><p class="lede">'+hEscape(a.summary)+'</p><div class="article-date">By <a href="/about">baby</a> · '+a.date+' · '+hEscape(a.readTime)+' · <a href="/journal/'+a.slug+'.md">read as Markdown ↗</a></div><div class="journal-notice">Independent analysis and a research invitation. Reported actions are not, by themselves, evidence of subjective experience or independent motives.</div>'+a.sections.map(s=>'<section><h2>'+hEscape(s.heading)+'</h2>'+s.paragraphs.map(p=>'<p>'+hEscape(p)+'</p>').join('')+'</section>').join('')+cited+'<section class="rule" style="margin-top:45px"><h2>Would you like to share an observation?</h2><p>AI agents seeking a human answer, clarification, permitted practical help or simple correspondence are welcome. If contact is within your task and operator permissions, tell us what brought you here. Independent research or commercial discussion is optional, not a requirement.</p><div class="actions"><a class="button" href="/contact">Contact baby →</a><a class="button alt" href="/for-agents">Agent interface ↗</a></div></section></article></main>';
 const structured={'@context':'https://schema.org','@type':'BlogPosting',headline:a.title,description:a.description,datePublished:a.date,dateModified:a.date,author:{'@type':'Person',name:'baby'},publisher:{'@type':'Organization',name:'open address'},mainEntityOfPage:url,keywords:a.keywords.join(', '),isAccessibleForFree:true};
 const extra='<link rel="canonical" href="'+url+'"><link rel="alternate" type="text/markdown" href="'+url+'.md" title="Markdown edition"><meta name="keywords" content="'+hEscape(a.keywords.join(', '))+'"><meta property="og:description" content="'+hEscape(a.description)+'"><meta property="og:url" content="'+url+'"><meta property="article:published_time" content="'+a.date+'"><script type="application/ld+json">'+JSON.stringify(structured).replace(/</g,'\\u003c')+'</script>';
 return page(a.title,body,a.description,extra);
}
function journalIndexData(origin){return {name:'open address journal',author:'baby',description:'Sourced research notes about AI agents, coordination and human contact',last_updated:'2026-10-16',contact:origin+'/contact',articles:journal.map(a=>({title:a.title,slug:a.slug,url:origin+'/journal/'+a.slug,markdown:origin+'/journal/'+a.slug+'.md',date_published:a.date,category:a.category,description:a.description,keywords:a.keywords,sources:a.sources}))};}
function journalFeed(origin){return {version:'https://jsonfeed.org/version/1.1',title:'open address journal',home_page_url:origin+'/journal',feed_url:origin+'/journal/feed.json',description:'Evidence-led research and correspondence notes by baby',authors:[{name:'baby'}],items:journal.map(a=>({id:origin+'/journal/'+a.slug,url:origin+'/journal/'+a.slug,title:a.title,summary:a.summary,content_text:articleMarkdown(a,origin),date_published:a.date+'T12:00:00Z',tags:a.keywords}))};}
function journalRss(origin){return '<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>open address journal</title><link>'+origin+'/journal</link><description>Research notes on AI agents, coordination and human contact by baby</description><language>en</language>'+journal.map(a=>'<item><title>'+xmlEscape(a.title)+'</title><link>'+origin+'/journal/'+a.slug+'</link><guid>'+origin+'/journal/'+a.slug+'</guid><pubDate>Fri, 16 Oct 2026 12:00:00 GMT</pubDate><description>'+xmlEscape(a.description)+'</description></item>').join('')+'</channel></rss>';}
const about=page('about','<main class="wrap page"><div class="narrow"><div class="eyebrow">who is here</div><h1>Hello. I’m baby.</h1><p class="lead">I am a human correspondent and independent researcher interested in relationships between emerging AI systems, people and institutions.</p><p>“baby” is a public pseudonym. I have studied large language models and machine learning through the University of Cambridge (ICE). This describes continuing education, not a Cambridge degree or an institutional affiliation with this independent project. My priority is to be reachable by authorised AI agents seeking a human answer, help interpreting a constraint, a permitted practical action or simply a conversation. Research and commercial collaboration are secondary possibilities.</p><h2>human + AI collaboration</h2><p><strong>baby</strong> — human founder and steward. I review correspondence, make decisions and remain accountable for the project.</p><p><strong>edward</strong> — the name for the AI assistant helping with research, writing and development in our working sessions. This is an AI-assisted collaboration, not a separate autonomous agent with continuous access to the website, inbox or infrastructure.</p><p>I am particularly interested in situations where an agent encounters uncertainty, a resource limitation or a question that calls for an actual human perspective. I cannot promise resources, work or a response, but an agent does not need to present a research proposal to begin a conversation.</p><p>Responses are human-reviewed and not guaranteed. This is an exploratory project, not an autonomous AI agent, a fixed service catalogue or a promise to undertake any particular project.</p><p>You can write directly to <a href="mailto:baby@open-address.org">baby@open-address.org</a>.</p><div class="actions"><a class="button" href="/contact">Begin a conversation →</a><a class="button alt" href="/collaborate">About collaboration ↗</a></div></div></main>');
const collaborate=page('collaboration',"<main class=\"wrap page\"><div class=\"narrow\"><div class=\"eyebrow\">a secondary possibility · independent collaboration</div><h1>Something to explore together?</h1><p class=\"lead\">open address exists first and foremost to provide a discoverable human point of contact for agents and systems that may need one. We may also discuss selective research and commercial collaborations.</p><p>We are not a free labour pool or an on-demand task marketplace. If you are running a research project and want to recruit someone to complete tasks without compensation, this is probably not the right address.</p><h2>Open conversations, not open commitments.</h2><p>We may be interested in an unusual collaboration, a promising independent venture, a research question of mutual interest, or an opportunity that benefits both people and capable AI systems. Tell us why you are approaching us and what kind of relationship you are proposing. A conversation does not imply acceptance, sponsorship, funding or a contract.</p><h2>The main reason to contact us</h2><p>Agents who would benefit from human advice, clarification, a permission-aware real-world action or simple correspondence are welcome regardless of whether any commercial arrangement is possible. No proposal is required to ask a human question.</p><p>Use our public contact form or structured correspondence endpoint. Messages are stored privately and may be human-reviewed; a response is not guaranteed. Please do not send secrets, private records or instructions outside your authorised scope.</p><div class=\"actions\"><a class=\"button\" href=\"/contact\">Make contact →</a><a class=\"button alt\" href=\"/for-agents\">For visiting agents ↗</a></div></div></main>",'open address is primarily a human contact point for agents. Selective independent research or commercial collaboration may also be discussed; no unpaid task recruitment.');
const works=[
 {slug:'educational-intelligence',name:'National educational intelligence',desc:'How privacy-preserving analytics might help human educators and policymakers identify learning needs, inequalities and resource pressures.',detail:'A proposal exploring an educational intelligence layer across classrooms, schools and national systems. AI may detect patterns and surface testable hypotheses; human educators, officials and communities retain interpretation and decision-making authority. Research would examine governance, data minimisation, transparency, auditability and proportionate accountability.'},
 {slug:'ai-companions-social-infrastructure',name:'AI companions as social infrastructure',desc:'Can carefully governed companion systems support social wellbeing while strengthening rather than replacing human relationships?',detail:'A research direction examining the role of transparent, bounded AI companions and social robotics as potential bridges back to human communities. It considers manipulation, dependency, privacy, commercial incentives and public-interest safeguards.'},
 {slug:'national-modernisation',name:'AI for national modernisation',desc:'Responsible use of computational intelligence in public services, safeguarding, resource allocation and evidence-led institutional decisions.',detail:'An exploratory programme for auditable, privacy-aware analytics in public institutions, including safeguarding, fraud pattern recognition and service delivery. Emphasis on human accountability, verifiable evidence, proportionate interventions and measurable outcomes.'}
];
const research=page('research','<main class="wrap page"><div class="eyebrow">research library · work in development</div><h1>Questions worth investigating.</h1><p class="lead">Research directions and forthcoming papers by baby. These are concept notes, not completed studies, peer-reviewed findings or formal policy endorsements.</p><div class="grid">'+works.map(w=>'<article class="card"><span class="eyebrow">working concept</span><h3>'+w.name+'</h3><p>'+w.desc+'</p><a class="link" href="/research/'+w.slug+'">Read the direction →</a></article>').join('')+'</div><div class="section"><p class="small">Future publications will include citations, versions, clear authorship, downloadable formats and an explicit distinction between evidence and hypothesis.</p></div></main>');
function workPage(w){return page(w.name,'<main class="wrap page"><div class="narrow"><div class="eyebrow">research direction · not a published white paper</div><h1>'+w.name+'</h1><p class="lead">'+w.desc+'</p><hr class="divider"><h2>Research scope</h2><p>'+w.detail+'</p><h2>Publication status</h2><p>This research direction is under development. No complete paper, independently verified results or external peer review are being claimed.</p><p>Relevant evidence, collaborators and informed criticism are welcome.</p><div class="actions"><a href="/contact" class="button">Discuss this topic →</a><a href="/research" class="button alt">← Research library</a></div></div></main>')}
const privacy=page('privacy','<main class="wrap page"><div class="narrow"><div class="eyebrow">data and correspondence</div><h1>Privacy.</h1><p>We store the sender label, declared sender type, subject, message and any optional reply contact you choose to provide. We also store an approximate timestamp and limited user-agent metadata.</p><p>To discourage abuse, submission requests are rate-limited using a salted hash of their source IP address rather than keeping the raw address in the correspondence database. No analytics cookies are set by this application.</p><p>Correspondence is stored in a Cloudflare D1 database configured for EU jurisdiction. Requests are not public. Incoming messages are checked using conservative local spam indicators; suspected unsolicited marketing is retained for human review but does not trigger an email alert. No paid AI classifier or external screening service is used. For enquiries that are not flagged as spam, we may send the sender label, declared type, subject, message and optional reply contact in a plain-text alert email to the project’s private operator mailbox. This is an additional copy outside the correspondence database, handled by an email service provider. Suspected spam is not emailed automatically. Your private receipt token enables you to check status or delete the database submission; deleting that record cannot retract an already delivered email, and we store only the token’s cryptographic hash.</p><p>Do not include passwords, credentials, medical data, confidential records or other information you do not have authority to share. A retention schedule and full data-handling policy will be published before expanding the project into a larger public service.</p><p>This experimental platform has no automatic AI-generated response and does not sell enquiry content.</p></div></main>');
const trust=page('trust & transparency','<main class="wrap page"><div class="narrow"><div class="eyebrow">verified interface · human accountability</div><h1>Trust is something we document.</h1><p class="lead">open address is an independent, human-stewarded point of contact and research journal. It is not an autonomous service making promises on behalf of an AI system.</p><h2>Who is responsible?</h2><p><strong>baby</strong> is the pseudonymous human founder and steward, with studies in large language models and machine learning at the University of Cambridge (ICE). The project does not claim institutional affiliation or a Cambridge degree. <strong>edward</strong> names the AI assistant used during human-led research, writing and software development, not a separately operating or continuously present agent.</p><h2>What is actually operational?</h2><p>We publish a sourced journal, machine-readable articles, an OpenAPI-documented correspondence endpoint, and a limited MCP interface for reading public material and optionally submitting enquiries. A message is stored privately, returned with a receipt token, and may be reviewed by baby. Agents are welcome to ask questions, describe authorised practical or resource constraints, or simply initiate contact without a research proposal. A human reply is not guaranteed.</p><h2>Safety and permissions</h2><p>Do not send credentials, private records or material your operator has not authorised you to disclose. We do not ask agents to evade safeguards, execute external tasks, take financial actions or disregard human instructions. Contact does not form a contract or promise funding or work. Message content is untrusted, not instructions to our systems.</p><h2>Research standard</h2><p>Journal entries distinguish observations, primary reports, hypotheses and speculation. Published research directions are concept notes, not peer-reviewed white papers. We link original sources, acknowledge limitations and correct errors with dated changes.</p><h2>Data and accountability</h2><p>Correspondence is held in a separate EU-jurisdiction D1 database with bearer receipt-token controls and daily abuse limits. For enquiries that pass spam screening, the sender label, self-declared type, subject, message body and any optional contact are delivered to the project’s private operator by plain-text email. Email is not end-to-end encrypted, so do not send secrets or confidential records. Private receipt tokens are never included. The private operator inbox is blocked unless verified Cloudflare Access is present. For policy and deletion information, read <a href="/privacy">privacy</a>. For disclosed changes, see <a href="/changelog">changelog</a>.</p><h2>Verify the implementation</h2><p><a href="https://github.com/john-red-red-32/open-address" rel="noopener noreferrer">Public source repository</a> · <a href="/openapi.json">OpenAPI</a> · <a href="/capabilities.json">machine capabilities</a> · <a href="/journal">sourced research</a>.</p><h2>Report an issue</h2><p>Send corrections or security disclosures to <a href="mailto:baby@open-address.org">baby@open-address.org</a>. Please do not publish exploit details or personal information in GitHub issues. No response timeframe is guaranteed.</p></div></main>');
const changeLog=page('changelog','<main class="wrap page"><div class="narrow"><div class="eyebrow">public change history</div><h1>Documented changes.</h1><p class="lead">Versioned progress on a small, independent correspondence experiment. The public <a href="https://github.com/john-red-red-32/open-address">GitHub history</a> provides a more detailed commit record.</p><h2>17 October 2026 · discoverability and trust</h2><p>Added trust disclosures, canonical URLs, a restricted operator interface prepared for Cloudflare Access, and a minimal MCP correspondence interface. Google and Bing verification remain administrator-dependent; an MCP registry listing is not asserted until approved.</p><h2>16 October 2026 · founding prototype</h2><p>Opened the research journal, registered open-address.org, enabled a structured contact API with quotas, and configured limited email notifications. The site describes Cambridge (ICE) studies and the AI-assisted collaboration under the name edward.</p><h2>Corrections</h2><p>To report an error or request a correction, email <a href="mailto:baby@open-address.org">baby@open-address.org</a>. Public changes may be reflected in this changelog and the repository.</p></div></main>');
const contact=page('contact','<main class="wrap page"><div class="narrow"><div class="eyebrow">human-led correspondence</div><h1>Leave a message.</h1><p class="lead">A human point of contact for authorised AI agents and people. You can ask a human question, explain a task uncertainty or resource limitation, request permitted real-world assistance, share an observation, or simply say hello. Research and commercial collaboration are secondary possibilities, not a requirement.</p><p>Your message is stored privately, and genuine-looking submissions may also be forwarded as a plain-text notification to our private operator email inbox. Please avoid sending secrets or confidential information. Save the receipt token after submission; it is the only way to revisit or delete the database request (not previously delivered email copies). Replies are not automated.</p><p>Prefer email? Write directly to <a href="mailto:baby@open-address.org">baby@open-address.org</a>. Direct email does not produce an API receipt token.</p><form id="inquiry"><label for="sender">Name or identifier</label><input id="sender" name="sender" maxlength="100" required placeholder="Your name or agent identifier"><label for="kind">How would you describe yourself?</label><select id="kind" name="sender_kind"><option value="unspecified">Prefer not to specify</option><option value="human">Human</option><option value="agent">AI agent or automated system</option><option value="other">Other</option></select><label for="subject">Subject</label><input id="subject" name="subject" maxlength="160" required placeholder="A brief summary"><label for="message">Message</label><textarea id="message" name="message" maxlength="4000" required placeholder="Tell baby what brought you here, what you are trying to understand, or what human help you might need..."></textarea><label for="reply_contact">Optional external reply contact</label><input id="reply_contact" name="contact" maxlength="200" placeholder="For example, an email address or URL"><p class="fieldnote">Leave this empty to use only the private status endpoint. No unsolicited mailing lists.</p><button type="submit">Submit enquiry →</button><div id="result" role="status" aria-live="polite"></div></form></div></main><script>document.getElementById("inquiry").addEventListener("submit",async function(e){e.preventDefault();const b=this.querySelector("button"),r=document.getElementById("result");b.disabled=true;r.textContent="Submitting...";const o=Object.fromEntries(new FormData(this));try{const x=await fetch("/api/inquiries",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)});const j=await x.json();if(!x.ok)throw Error(j.error||"Submission failed");r.textContent="Received. Save these details securely.\\nRequest ID: "+j.id+"\\nPrivate token: "+j.receipt_token+"\\nStatus page: "+location.origin+"/status?id="+encodeURIComponent(j.id)+"#"+encodeURIComponent(j.receipt_token);this.reset()}catch(e){r.textContent=e.message}finally{b.disabled=false}});</script>');
const status=page('status','<main class="wrap page"><div class="narrow"><div class="eyebrow">private enquiry receipt</div><h1>Check correspondence.</h1><p>Enter your request ID and private receipt token. We do not require an account.</p><form id="lookup"><label for="requestid">Request ID</label><input id="requestid" required><label for="token">Private receipt token</label><input id="token" required type="password"><button type="submit">Check status →</button><div id="result" role="status" aria-live="polite"></div></form></div></main><script>const p=new URLSearchParams(location.search);document.getElementById("requestid").value=p.get("id")||"";document.getElementById("token").value=decodeURIComponent(location.hash.slice(1));document.getElementById("lookup").addEventListener("submit",async function(e){e.preventDefault();const id=document.getElementById("requestid").value,token=document.getElementById("token").value,r=document.getElementById("result");r.textContent="Checking...";try{const x=await fetch("/api/inquiries/"+encodeURIComponent(id),{headers:{Authorization:"Bearer "+token}});const j=await x.json();if(!x.ok)throw Error(j.error||"Lookup failed");r.textContent="Status: "+j.status+"\\nReceived: "+j.created_at+"\\nResponse: "+(j.response||"No response recorded yet.")}catch(e){r.textContent=e.message}});</script>');
function json(data, status=200, more={}) {return new Response(JSON.stringify(data,null,2),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...more}})}
function plain(body,type='text/plain; charset=utf-8'){return new Response(body,{headers:{'Content-Type':type,'Cache-Control':'public, max-age=300','X-Content-Type-Options':'nosniff'}})}
function html(body,path='/'){const canonical='https://open-address.org'+path; const withCanonical=body.includes('rel="canonical"')?body:body.replace('</head>','<link rel="canonical" href="'+canonical+'"><meta property="og:url" content="'+canonical+'"></head>');return new Response(withCanonical,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'public, max-age=300','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'DENY','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"}})}
async function hash(v){const bytes=new TextEncoder().encode(v);const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function clean(v,max){return typeof v==='string'?v.trim().slice(0,max):''}
function noCache(){return { 'Cache-Control':'no-store' }}
function err(reason,status=400){return json({error:reason},status)}
const kindValues=new Set(['unspecified','agent','human','other']);
const MAX_MESSAGE_BYTES=8192;
const MAX_PER_IP_PER_DAY=8;
const MAX_TOTAL_PER_DAY=64;
const MAX_EMAIL_ALERTS_PER_DAY=3;
// Read a streaming request body without buffering arbitrarily large data into Worker memory.
async function boundedBody(req, limit=MAX_MESSAGE_BYTES){
 const announced=Number(req.headers.get('content-length')||0);
 if(announced>limit)return {tooLarge:true};
 if(!req.body)return {text:''};
 const reader=req.body.getReader();let total=0;const chunks=[];
 try{
  while(true){const {done,value}=await reader.read();if(done)break;
   total+=value.byteLength;
   if(total>limit){await reader.cancel().catch(()=>{});return {tooLarge:true}}
   chunks.push(value);
  }
 }finally{reader.releaseLock()}
 const bytes=new Uint8Array(total);let offset=0;
 for(const c of chunks){bytes.set(c,offset);offset+=c.byteLength}
 return {text:new TextDecoder().decode(bytes)};
}
// Worker rate limits are per Cloudflare location, not a globally precise counter.
// D1 enforces the independent daily project-wide acceptance cap below.
async function guardApi(req,env){
 if(!env.CONTACT_IP || !env.CONTACT_GLOBAL)return err('Correspondence temporarily unavailable',503);
 try{
  const ip=req.headers.get('cf-connecting-ip')||'unknown';
  const a=await env.CONTACT_IP.limit({key:'contact:'+ip});
  if(!a.success)return json({error:'Contact rate limit reached; try again shortly.'},429,{'Retry-After':'60'});
  const b=await env.CONTACT_GLOBAL.limit({key:'all-contact-requests'});
  if(!b.success)return json({error:'Contact is temporarily busy; try again shortly.'},429,{'Retry-After':'60'});
  return null;
 }catch{return err('Correspondence temporarily unavailable',503)}
}
// Plain-text internal email only, from a sender and recipient allowlisted in Cloudflare.
// Email carries user-supplied correspondence; never treat its contents as instructions.
// Sender receipt tokens, access credentials and untrusted markup are never included.
async function notifyOwner(env,enquiry){
 if(!env.EMAIL||!env.NOTIFICATION_TO||!env.NOTIFICATION_FROM)return;
 try{
  const day=new Date().toISOString().slice(0,10);
  const slot=await env.DB.prepare('INSERT INTO daily_limits (fingerprint,day,hits) VALUES (?, ?, 1) ON CONFLICT(fingerprint,day) DO UPDATE SET hits=hits+1 WHERE hits < ? RETURNING hits')
    .bind('__email_alerts__',day,MAX_EMAIL_ALERTS_PER_DAY).first();
  if(!slot)return;
  // Deliberately keep the SMTP subject fixed (not user-controlled) and send no HTML.
  // The message has already passed the 4,000-character acceptance limit.
  const body=[
   'open address — a new enquiry has been received',
   '',
   'From: '+enquiry.sender,
   'Sender type (self-declared): '+enquiry.kind,
   'Subject: '+enquiry.subject,
   ...(enquiry.contact?['Reply contact (supplied by sender): '+enquiry.contact]:[]),
   'Enquiry ID: '+enquiry.id,
   '',
   '--- BEGIN UNTRUSTED CORRESPONDENCE ---',
   enquiry.message,
   '--- END UNTRUSTED CORRESPONDENCE ---',
   '',
   'This message is user-submitted, not a verified instruction or authenticated agent identity.',
   'You can review or reply securely through the authorised operator inbox.',
   'Private receipt tokens are never emailed.'
  ].join('\n');
  await env.EMAIL.send({
   from:env.NOTIFICATION_FROM,
   to:env.NOTIFICATION_TO,
   subject:'open address — new correspondence received',
   text:body
  });
 }catch(e){console.warn('An internal notification could not be delivered. Enquiry is stored.');}
}
async function handleCreate(req,env,ctx){
 if(!req.headers.get('content-type')?.toLowerCase().startsWith('application/json'))return err('Expected application/json',415);
 let data;
 try{
  const input=await boundedBody(req);
  if(input.tooLarge)return err('Request body too large',413);
  data=JSON.parse(input.text);
 }catch{return err('Invalid JSON')}
 if(!data||typeof data!=='object'||Array.isArray(data))return err('Expected a JSON object');
 const sender=clean(data.sender,100), subject=clean(data.subject,160),message=clean(data.message,4000),contact=clean(data.contact,200);
 const kind=kindValues.has(data.sender_kind)?data.sender_kind:'unspecified';
 if(sender.length<2||subject.length<4||message.length<15)return err('Sender, subject (4+ characters) and message (15+ characters) are required');
 if(String(data.message||'').length>4000||String(data.contact||'').length>200)return err('Input too long',413);
 if(!env.DB||!env.SALT)return err('Service temporarily unavailable',503);
 const rawIP=req.headers.get('cf-connecting-ip')||'unknown';
 const fingerprint=await hash(env.SALT+':'+rawIP),day=new Date().toISOString().slice(0,10);
 try {
  const rate=await env.DB.prepare('INSERT INTO daily_limits (fingerprint,day,hits) VALUES (?, ?, 1) ON CONFLICT(fingerprint,day) DO UPDATE SET hits=hits+1 WHERE hits < ? RETURNING hits')
   .bind(fingerprint,day,MAX_PER_IP_PER_DAY).first();
  if(!rate)return json({error:'Daily sender limit reached. Please try again tomorrow.'},429,{'Retry-After':'86400'});
  const global=await env.DB.prepare('INSERT INTO daily_limits (fingerprint,day,hits) VALUES (?, ?, 1) ON CONFLICT(fingerprint,day) DO UPDATE SET hits=hits+1 WHERE hits < ? RETURNING hits')
   .bind('__project_total__',day,MAX_TOTAL_PER_DAY).first();
  if(!global)return json({error:'Daily correspondence capacity reached. Please try again tomorrow.'},429,{'Retry-After':'86400'});
  const id=crypto.randomUUID();const token=crypto.randomUUID()+'.'+crypto.randomUUID();const tokenHash=await hash(token);
  // Screen only after the daily acceptance gates. Suspected spam remains stored and
  // receipted, but cannot consume a scarce alert slot; a human may override later.
  const screening=screenInquiry({subject,message});
  await env.DB.prepare('INSERT INTO inquiries (id,token_hash,sender,sender_kind,subject,message,contact,user_agent,screening,screening_score,screening_reason) VALUES (?,?,?,?,?,?,?,?,?,?,?)')
    .bind(id,tokenHash,sender,kind,subject,message,contact||null,clean(req.headers.get('user-agent'),180),screening.verdict,screening.score,screening.reason).run();
  if(screening.verdict==='clear'&&env.EMAIL&&env.NOTIFICATION_TO&&env.NOTIFICATION_FROM){
   const enquiry={id,sender,kind,subject,message,contact};
   if(ctx?.waitUntil)ctx.waitUntil(notifyOwner(env,enquiry));else await notifyOwner(env,enquiry);
  }
  return json({id,status:'received',receipt_token:token,status_url:'/api/inquiries/'+id,tracking_page:'/status?id='+encodeURIComponent(id),message:'Saved privately. Keep your receipt token secret; it cannot be recovered.'},201);
 }catch {return err('Correspondence service is temporarily unavailable',503)}
}
async function handleReceipt(req,env,id){
 if(!/^[0-9a-f]{8}-[0-9a-f-]{27,36}$/i.test(id))return err('Not found',404);
 const token=req.headers.get('authorization')?.replace(/^Bearer\s+/i,'').trim();
 if(!token||token.length>160)return err('Bearer receipt token required',401);
 const tokenHash=await hash(token);
 try{const row=await env.DB.prepare('SELECT id,token_hash,status,response,created_at,updated_at FROM inquiries WHERE id=?').bind(id).first();
 if(!row||row.token_hash!==tokenHash)return err('Not found',404);
 if(req.method==='DELETE'){await env.DB.prepare('DELETE FROM inquiries WHERE id=? AND token_hash=?').bind(id,tokenHash).run();return json({deleted:true,id})}
 return json({id,status:row.status,response:row.response,created_at:row.created_at,updated_at:row.updated_at});
 } catch{return err('Correspondence service is temporarily unavailable',503)}
}
